lessons.wrong_pattern:
@Component
export struct XxxView {
  @Prop ctx: Record<string, ESObject>
  // 没有 tag 属性
  // 没有 subscribeToDescriptorChanges
  // 没有 EventEmitter
}

lessons.fix_pattern:
必须使用 RNOH 标准 Fabric 组件模式：

@Component
export struct XxxView {
  public ctx!: RNOHContext;       // 必须是 RNOHContext
  public tag: number = 0;        // 必须有 tag
  @State private propA: string = '';
  private eventEmitter: RNC.XxxView.EventEmitter | undefined = undefined;
  private cleanUpCallbacks: (() => void)[] = [];

  aboutToAppear() {
    this.eventEmitter = new RNC.XxxView.EventEmitter(this.ctx.rnInstance, this.tag);
    this.cleanUpCallbacks.push(
      this.ctx.descriptorRegistry.subscribeToDescriptorChanges(this.tag, (descriptor) => {
        const rawProps = descriptor.rawProps as RNC.XxxView.DirectRawProps;
        this.propA = rawProps.propA ?? '';
      })
    );
  }

  aboutToDisappear() {
    this.cleanUpCallbacks.forEach(cb => cb());
  }

  build() {
    RNViewBase({ ctx: this.ctx, tag: this.tag }) {
      // ArkUI 组件
    }
  }
}

lessons.wrong_pattern:
import { RNComponentContext, RNViewBase, RNViewBaseAttributeModifier, ViewDescriptorWrapperBase, DescriptorWrapper } from '@rnoh/react-native-openharmony/ts';

@Component
export struct PinchableView {
  public ctx!: RNComponentContext;
  // ...
  build() {
    Stack() {
      LazyForEach(this.ctx.createComponentDataSource({ tag: this.tag }),
        (dw: DescriptorWrapper) => {
          this.ctx.wrappedRNComponentBuilder.builder(this.ctx, dw.tag)
        }, ...)
    }
  }
}

编译报错示例：
- Module '"@rnoh/react-native-openharmony/ts"' has no exported member 'RNViewBase'
- Use explicit types instead of "any", "unknown" (arkts-no-any-unknown)
- wrappedRNComponentBuilder.builder(...) does not meet UI component syntax

lessons.fix_pattern:
UI 运行时符号从主包导入（勿用 /ts）；codegen 生成的 Spec 仍可从 /ts 导入：

import { RNOHContext, RNComponentContext, DescriptorWrapper } from '@rnoh/react-native-openharmony';
import { ViewBaseDescriptor, ViewDescriptorWrapperBase, RNViewBaseAttributeModifier } from '@rnoh/react-native-openharmony';
import { PinchableView as Spec } from '../generated/components/PinchableView';

@Component
export struct PinchableView {
  public ctx!: RNOHContext;
  public tag: number = 0;
  // subscribeToDescriptorChanges + EventEmitter ...
  build() {
    Stack() {
      if (this.ctx instanceof RNComponentContext) {
        LazyForEach(this.ctx.createComponentDataSource({ tag: this.tag }),
          (descriptorWrapper: DescriptorWrapper) => {
            (this.ctx as RNComponentContext).wrappedRNComponentBuilder.builder(
              (this.ctx as RNComponentContext),
              descriptorWrapper.tag
            )
          },
          (descriptorWrapper: DescriptorWrapper) => descriptorWrapper.tag.toString() + '@' + descriptorWrapper.renderKey
        )
      }
    }
    .attributeModifier(this.rnViewAttributeModifier)
    // 自定义手势/scale 等加在 Stack 上
  }
}

说明：
- /ts 子路径主要导出 Descriptor、EventEmitter 等 codegen 类型，不含 RNViewBase、RNViewBaseAttributeModifier
- 需要渲染 RN 子节点时，子节点 LazyForEach 模式对齐 RNView.ets（instanceof RNComponentContext + 显式 cast）
- 仅展示占位 UI、无子节点时，可用 generate_library_common 模板的 RNViewBase({ ctx, tag }) { ... }

在 Package 中添加 createDescriptorWrapperFactoryByDescriptorType 方法：

createDescriptorWrapperFactoryByDescriptorType(
  ctx: DescriptorWrapperFactoryByDescriptorTypeCtx
): DescriptorWrapperFactoryByDescriptorType {
  const result: DescriptorWrapperFactoryByDescriptorType = {};
  result[RNC.XxxView.NAME] = (ctx) =>
    new RNC.XxxView.DescriptorWrapper(ctx.descriptor);
  return result;
}

lessons.wrong_pattern:
// Image.onComplete 中硬编码数据
.onComplete(() => {
  this.eventEmitter?.emit('onLoad', { width: 0, height: 0 });
})

lessons.fix_pattern:
使用 ArkUI 回调函数提供的真实 event 参数：

