lessons.wrong_pattern:
TurboModule 中 write 方法只从 clientSockets Map 查找 socket：
const instance = this.clientSockets.get(cId);
if (!instance) { callback('Socket not found'); return; }

服务端 accept 接受的客户端连接存放在 serverSockets[serverId].clientSockets 中，导致服务端连接无法写入数据。

lessons.fix_pattern:
write 方法应同时查找 clientSockets 和 serverSockets 中的客户端连接：

1. 先从 clientSockets 查找
2. 找不到则遍历 serverSockets，检查每个 serverInst.clientSockets
3. 将写入逻辑提取为独立方法避免代码重复

private writeToSocket(tcpSocket: socket.TCPSocket, cId: number, base64String: string, callback: (error: string) => void): void {
  const decodedData = this.base64Helper.decodeSync(base64String);
  const arrayBuffer = decodedData.buffer.slice(decodedData.byteOffset, decodedData.byteOffset + decodedData.byteLength);
  tcpSocket.send({ data: arrayBuffer }).then(() => { ... });
}

write(cId: number, base64String: string, callback?: (error: string) => void): void {
  const instance = this.clientSockets.get(cId);
  if (instance) { this.writeToSocket(instance.socket, cId, base64String, callback); return; }

  for (const [serverId, serverInst] of this.serverSockets) {
    const clientSocket = serverInst.clientSockets.get(cId);
    if (clientSocket) { this.writeToSocket(clientSocket, cId, base64String, callback); return; }
  }

  if (callback) callback('Socket not found');
}
